class Solution:
    def differenceOfSum(self, nums: List[int]) -> int:
        es = sum(nums)
        ds = 0
        for x in nums:
            while x:
                ds += x % 10
                x //= 10
        return abs(es - ds)

c.cpp:
class Solution {
public:
    int differenceOfSum(vector<int>& nums) {
        long long es = accumulate(nums.begin(), nums.end(), 0LL), ds = 0;
        for (int x : nums) for (; x; x /= 10) ds += x % 10;
        return (int)abs(es - ds);
    }
};

c.java:
class Solution {
    public int differenceOfSum(int[] nums) {
        int es = 0, ds = 0;
        for (int x : nums) {
            es += x;
            while (x > 0) { ds += x % 10; x /= 10; }
        }
        return Math.abs(es - ds);
    }
}

