var differenceOfSum = function(nums) {
    let es = 0, ds = 0;
    for (const x of nums) {
        es += x;
        let v = x;
        while (v > 0) { ds += v % 10; v = Math.floor(v / 10); }
    }
    return Math.abs(es - ds);
};

